$ErrorActionPreference='Stop'
$base='http://127.0.0.1:5088'
$outbox=Join-Path $env:TEMP 'opencode\lavafacil-mail-outbox'
$checks=@()
function C($n,$ok,$d){$script:checks += [pscustomobject]@{prueba=$n;estado=if($ok){'PASS'}else{'FAIL'};detalle=$d}}
function Req($s,$m,$p,$b=$null,$headers=@{}) { $h=@{}; foreach($x in $headers.GetEnumerator()){$h[$x.Key]=$x.Value}; try {$r=Invoke-WebRequest -UseBasicParsing -WebSession $s -Method $m -Uri ($base+$p) -Headers $h -ContentType 'application/json' -Body ($(if($null -ne $b){$b|ConvertTo-Json -Compress}else{$null}));[pscustomobject]@{Status=[int]$r.StatusCode;Body=$r.Content}} catch {if($_.Exception.Response){$rr=$_.Exception.Response;$sr=New-Object IO.StreamReader($rr.GetResponseStream());[pscustomobject]@{Status=[int]$rr.StatusCode;Body=$sr.ReadToEnd()}}else{throw}}}
function Csrf($s){(Req $s 'GET' '/api/bootstrap').Body|ConvertFrom-Json}
$stamp=[DateTime]::UtcNow.ToString('yyyyMMddHHmmss');$u="autotest.cookie.$stamp";$e="$u@example.com";# Clave de fixture generada en tiempo de ejecución; no se versiona ningún valor real.
$pw=if($env:LAVAFACIL_TEST_PASSWORD){$env:LAVAFACIL_TEST_PASSWORD}else{'Temporal-'+[guid]::NewGuid().ToString('N')+'!Aa1'};$a=New-Object Microsoft.PowerShell.Commands.WebRequestSession;$b=New-Object Microsoft.PowerShell.Commands.WebRequestSession
$bj=Csrf $a;$r=Req $a 'POST' '/api/register' @{identity="CO-$stamp";name='AUTO';lastName='COOKIE';phone='5551234567';email=$e;address='prueba';username=$u;password=$pw} @{'X-CSRF-TOKEN'=$bj.token};C 'registro para invalidacion de cookie' ($r.Status -eq 200) "status=$($r.Status)"
$bj=Csrf $b;$r=Req $b 'POST' '/api/email/recuperacion/solicitar' @{identificador=$e} @{'X-CSRF-TOKEN'=$bj.token};Start-Sleep -Milliseconds 250;$files=@(Get-ChildItem $outbox -Filter *.eml|Where-Object{$_.LastWriteTime -gt (Get-Date).AddMinutes(-2)}|Sort-Object LastWriteTime);$f=$files|Where-Object{(Get-Content -Raw $_.FullName) -match [regex]::Escape($e)}|Select-Object -Last 1;$txt=if($f){Get-Content -Raw $f.FullName}else{''};$code=[regex]::Match($txt,'(?im)^Codigo:\s*(\d{6})\s*$').Groups[1].Value;$sinHeader=($txt -notmatch '(?im)^X-LavaFacil-Codigo\s*:');$sinOtpSubject=($txt -notmatch '(?im)^Subject:.*\d{6}');C 'recuperacion extrae OTP solo de Codigo en cuerpo' ($code.Length -eq 6) "codigoExtraidoDelCuerpo=$($code.Length -eq 6)";C 'recuperacion no tiene header OTP ni OTP en Subject' ($sinHeader -and $sinOtpSubject) "sinHeader=$sinHeader; sinOtpSubject=$sinOtpSubject"
$bj=Csrf $b;$new=if($env:LAVAFACIL_TEST_PASSWORD){$env:LAVAFACIL_TEST_PASSWORD}else{'Temporal-'+[guid]::NewGuid().ToString('N')+'!Aa1'};$r=Req $b 'POST' '/api/email/recuperacion/restablecer' @{identificador=$e;codigo=$code;nuevaClave=$new} @{'X-CSRF-TOKEN'=$bj.token};C 'reset de clave para invalidar cookie previa' ($r.Status -eq 200 -and $code.Length -eq 6) "status=$($r.Status); codigo=$($code.Length -eq 6)"
$observed=$false;$last=$null;for($i=0;$i -lt 35;$i++){Start-Sleep -Seconds 1;$bj=Csrf $a;$last=Req $a 'GET' '/api/home';if($last.Status -eq 401){$observed=$true;break}};C 'cookie previa invalidada en hasta 35s' $observed "statusFinal=$($last.Status); segundos=$($i+1)"
$bj=Csrf $a;$r=Req $a 'POST' '/api/login' @{username=$u;password=$new} @{'X-CSRF-TOKEN'=$bj.token};C 'login con clave posterior al reset' ($r.Status -eq 200) "status=$($r.Status)"
$anon=New-Object Microsoft.PowerShell.Commands.WebRequestSession;$bj=Csrf $anon;$r=Req $anon 'POST' '/api/register' @{identity='bad-csrf';name='A';lastName='B';phone='5551234567';email="csrf-$stamp@example.com";address='x';username="csrf-$stamp";password=$pw};C 'CSRF rechaza POST sin token' ($r.Status -eq 400) "status=$($r.Status); cuerpo=$($r.Body)"
$h=@{'Host'='evil.example'};$r=Req $anon 'GET' '/api/bootstrap' $null $h;C 'Host no permitido' ($r.Status -eq 403) "status=$($r.Status); cuerpo=$($r.Body)"
$bj=Csrf $a;$r=Req $a 'GET' '/api/clients';C 'GET clients como Cliente 403' ($r.Status -eq 403) "status=$($r.Status); cuerpo=$($r.Body)"
$clean=New-Object Microsoft.PowerShell.Commands.WebRequestSession;$r=Req $clean 'GET' '/api/health';C 'mirroring/health no publicado 404' ($r.Status -eq 404) "status=$($r.Status); cuerpo=$($r.Body)"
$r=Req $clean 'GET' '/';C 'raiz publica' ($r.Status -eq 200) "status=$($r.Status)"
$r=Req $clean 'GET' '/monitor.js';C 'recurso no publicado' ($r.Status -eq 404) "status=$($r.Status)"
$checks|ConvertTo-Json -Depth 4
